    return;

// Let HP2's Mounting/MountFinish finish the root-motion climb. The input
// bootstrap below would otherwise GotoState(PlayerWalking) every frame,
// interrupting the climb and its temporary collision-size restoration.
if (IsInState('Mounting') || IsInState('MountFinish'))
{
    aForward = 0.0;
    aStrafe = 0.0;
    bPressedJump = False;
    bVersusJumpWasDown = bVersusJump;
    return;
}

